WITH filtered AS (SELECT *, COALESCE(city, 'Unknown') AS city_filled, LOWER(country) AS country_lower FROM suppliers WHERE city IS NOT NULL AND city IS DISTINCT FROM 'Chiang Mai') SELECT *, LEAD(rating) OVER (PARTITION BY country, city ORDER BY rating, id) AS next_rating, LAG(rating) OVER (PARTITION BY country, city ORDER BY rating, id) AS prev_rating, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating, id) AS event_seq, ROUND(rating / SUM(rating) OVER (PARTITION BY city), 4) AS rating_share FROM filtered
